@js:
var html = String(result);
var m = html.match(/var player_aaaa=(\{[\s\S]*?\})\s*<\/script>/);
if (!m) {
    m = html.match(/var player_aaaa=(\{[\s\S]*?\})/);
}
if (m) {
    try {
        var data = JSON.parse(m[1]);
        result = data.url || '';
    } catch (e) {
        var u = m[1].match(/"url"\s*:\s*"([^"]+)"/);
        result = u ? u[1] : '';
    }
} else {
    var u2 = html.match(/"url"\s*:\s*"([^"]+)"/);
    result = u2 ? u2[1] : '';
}
result = String(result).replace(/\\\//g, '/');
result
